package com.nexbank.notification.service;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.util.UUID;
@Component public class NotificationConsumer {private final ObjectMapper mapper;private final JdbcTemplate jdbc;public NotificationConsumer(ObjectMapper m,JdbcTemplate j){mapper=m;jdbc=j;}
 @KafkaListener(topics={"transfer-completed","fraud-detected","account-frozen","account-freeze-requested"},groupId="notification-service") @Transactional public void consume(String payload){try{JsonNode n=mapper.readTree(payload);UUID event=UUID.fromString(n.path("eventId").asText());if(jdbc.queryForObject("select count(*) from processed_events where event_id=?",Integer.class,event)>0)return;String type=n.path("eventType").asText("transfer-completed");String message="Banking event received: "+type;jdbc.update("insert into notifications(id,user_id,message,status) values (?,?,?,'LOGGED')",UUID.randomUUID(),UUID.fromString(n.path("userId").asText()),message);jdbc.update("insert into audit_log(id,event_type,payload) values (?,?,?::jsonb)",UUID.randomUUID(),type,payload);jdbc.update("insert into processed_events(event_id) values (?)",event);}catch(Exception e){throw new IllegalArgumentException("Invalid notification event",e);}}
}
